//! Canonical Option value with exact attributes and HTML-aware text fallback.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><optgroup id=optgroup label=Group><option id=option label=Group value=one>One</option></optgroup><option value=two>Two</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn option_value_canonical_interface_descriptors_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'value');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get value'||a.set.name!=='set value'||Object.hasOwn(x,'value')||x.value!=='one'||x.firstChild.textContent!=='One')throw 'canonical option metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal optgroup construction';"#);}
#[test]
fn option_value_exact_native_setter_aliases_and_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),a=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.value='A\ud800Z';var records=watch.takeRecords();if(x.value!=='A\ud800Z'||a.value!==x.value||x.getAttributeNode('value')!==a||records.length!==1||records[0].attributeName!=='value'||records[0].oldValue!=='one'||x.firstChild.textContent!=='One')throw 'exact option setter';a.nodeValue='not a date';if(x.value!=='not a date'||a.value!=='not a date')throw 'label is plain reflection';x.removeAttribute('value');if(x.value!=='One'||a.ownerElement!==null||a.value!=='not a date')throw 'removed label default';"#);}
#[test]
fn option_value_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.value={toString:function(){calls++;x.removeAttribute('value');x.setAttribute('value','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('value'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='one'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.value={toString:function(){x.setAttribute('value','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.value!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.value=Symbol('optgroup');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.value!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.value=value;if(x.value!==String(value))throw 'ordinary DOMString conversion';}if(x.firstChild.textContent!=='One')throw 'metadata leaves displayed text';"#);
}



#[test]
fn option_value_native_absent_empty_and_selected_control_state(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();
 run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),select=document.getElementById('select');x.value='Changed';if(x.value!=='Changed'||select.value!=='Changed'||x.label!=='Group')throw 'selected actual value';");assert_eq!(f.controls[&select].value.text(),"Changed");assert_eq!(f.controls[&select].select.as_ref().unwrap().options[0].value,"Changed");assert_eq!(f.controls[&select].caption,"Group");
 run(&mut d,&mut f,&mut p,"x.value='';if(x.value!==''||select.value!==''||x.getAttribute('value')!=='')throw 'present empty option value';x.removeAttribute('value');if(x.value!=='One'||select.value!=='One'||x.label!=='Group')throw 'absent normalized text fallback';");assert_eq!(f.controls[&select].value.text(),"One");assert_eq!(f.controls[&select].select.as_ref().unwrap().options[0].value,"One");
}
#[test]
fn option_value_inert_html_aware_fallback_and_exact_raw_attribute(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),script=owner.createElementNS('http://www.w3.org/1999/xhtml','script');x.appendChild(owner.createTextNode('  A\t'));script.textContent='Hidden';x.appendChild(script);x.appendChild(owner.createTextNode(' B\ud800Z  '));if(x.value!=='A B\ud800Z')throw 'actual inert value fallback';x.value='R\ud800Z';if(x.value!=='R\ud800Z'||x.getAttribute('value')!=='R\ud800Z')throw 'raw value attribute';x.value='';if(x.value!=='')throw 'empty present value';x.removeAttribute('value');if(x.value!=='A B\ud800Z')throw 'fallback recovery';"#);
}
#[test]
fn option_value_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'value'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OPTGROUP')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'value',{value:'author',writable:true,configurable:true});if(x.value!=='author'||a.get.call(x)!=='one')throw 'canonical authority';a.set.call(x,'canonical');if(x.value!=='author'||x.getAttribute('value')!=='canonical')throw 'borrowed real setter';delete x.value;if(x.value!=='canonical'||Object.hasOwn(x,'value'))throw 'restored inherited reflection';delete window.HTMLOptionElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn option_value_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLOptionElement,a=Object.getOwnPropertyDescriptor(C.prototype,'value'),calls=0;if(C===HTMLOptionElement||a.get.call(x)!=='one')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://option-value.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn option_value_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.value='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('value','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.setAttribute('value','one');"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked,format!("{:?}",c.select),c.caption.clone())).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='one'||x.value!=='one'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.value!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='one'||records[0].attributeName!=='value'||x.getAttributeNode('value')!==attr)throw 'fresh alt writer recovery';");
 }}}
}

#[test]
fn option_value_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');time.value='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('option').value='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("option")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_value_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_value_get(object).is_ok());}}
}



#[test]
fn option_value_native_and_inert_exact_attached_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.setAttribute('value','one');"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,if inert{"var expectedRemoved='';"}else{"var expectedRemoved='One';"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('value');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.value!=='R\ud800'+writer||x.getAttributeNode('value')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','value','foreign');x.setAttributeNS(null,'VALUE','upper');if(x.value!=='R\ud800textContent'||x.getAttributeNodeNS(null,'value')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'value','alternative');if(x.value!=='alternative'||a.value!==x.value)throw 'null namespace writer';x.removeAttributeNS(null,'value');if(x.value!==expectedRemoved||a.ownerElement!==null||a.value!=='alternative')throw 'removed actual alt';"#);}
}


#[test]
fn option_value_fallback_reads_refuse_atomically_and_recover_in_native_and_inert_trees(){
 for inert in [false,true]{for mode in 0..5{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.appendChild(x.ownerDocument.createTextNode(' A\ud800Z '));"}else{"var x=document.getElementById('option');x.removeAttribute('value');"});
  let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual option")};p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};
  let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_value_get(object).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("time")||error.contains("bound"),"{inert}/{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len()),before);
  p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,if inert{r"if(x.value!=='A\ud800Z')throw 'fresh raw fallback read';"}else{"if(x.value!=='One')throw 'fresh native fallback read';"});
 }}
}
#[test]
fn option_value_html_aware_namespace_whitespace_and_small_output_admission(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),svg=owner.createElementNS('http://www.w3.org/2000/svg','script'),foreign=owner.createElementNS('urn:foreign','script');x.appendChild(owner.createTextNode('\tA\n'));svg.appendChild(owner.createTextNode('Excluded SVG'));x.appendChild(svg);foreign.appendChild(owner.createTextNode('Foreign'));x.appendChild(foreign);x.appendChild(owner.createComment('Excluded comment'));x.appendChild(owner.createTextNode('\r\f \u000b\u00a0\u2003 Z\t'));if(x.value!=='A Foreign \u000b\u00a0\u2003 Z')throw 'namespace and exact ASCII whitespace';var compact=owner.createElementNS('http://www.w3.org/1999/xhtml','option'),large='';for(var n=0;n<500;n++)large+=' ';compact.appendChild(owner.createTextNode(large+'A'+large));"#);
 let Value::Host(object)=p.runtime.execute("compact;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual compact option")};let limit=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=1;p.begin_job();let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.option_value_get(object).unwrap();assert!(matches!(result,Value::String(ref text) if text=="A"));p.state.limits.host.string_bytes=limit;assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
}

#[test]
fn option_value_unselected_updates_preserve_current_editor_caption_selection_and_events(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();
 run(&mut d,&mut f,&mut p,"var select=document.getElementById('select'),first=document.getElementById('option'),second=select.lastChild,events=0;select.oninput=function(){events++;};select.onchange=function(){events++;};select.selectedIndex=1;");
 {let value=&mut f.controls.get_mut(&select).unwrap().value;value.cursor=2;value.anchor=1;value.offset=1;}
 let c=&f.controls[&select];let before=(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select.as_ref().unwrap().selected),c.dirty_value);
 run(&mut d,&mut f,&mut p,"first.value='Unselected changed';if(first.value!=='Unselected changed'||select.value!=='two'||events)throw 'unselected value state';");let c=&f.controls[&select];assert_eq!((c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),format!("{:?}",c.select.as_ref().unwrap().selected),c.dirty_value),before);
 run(&mut d,&mut f,&mut p,r"second.value='A\r\nB';if(select.value!=='A\r\nB'||second.value!=='A\r\nB'||events)throw 'exact unsanitized selected value';");let c=&f.controls[&select];assert_eq!(c.value.text(),"A\r\nB");assert_eq!((c.value.cursor,c.value.anchor,c.value.offset),(4,4,0));assert_eq!(c.caption,"Two");
 run(&mut d,&mut f,&mut p,"select.selectedIndex=-1;first.value='No selection';if(select.value!==''||events)throw 'no selection preserved';");assert_eq!(f.controls[&select].value.text(),"");assert_eq!(f.controls[&select].caption,"");
}
#[test]
fn option_value_native_unit_limit_stable_storage_and_combined_selected_payload_refusal(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),edge='',over='';for(var n=0;n<4096;n++)edge+='a';over=edge+'b';x.value=edge;");let retained=p.state.retained;for _ in 0..3{p.begin_job();run(&mut d,&mut f,&mut p,"x.value=edge;");assert_eq!(p.state.retained,retained);assert_eq!(f.controls[&select].value.chars.len(),4096);}
 let tree=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);let editor=f.controls[&select].value.text();p.begin_job();let error=p.runtime.execute("x.value=over;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("4096"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(format!("{:?}",f.controls[&select].select),native);assert_eq!(f.controls[&select].value.text(),editor);
 p.begin_job();run(&mut d,&mut f,&mut p,"x.value='one';");
 let payload=f.controls.values().map(|c|{let mut n=c.name.len()+c.value.chars.iter().map(|ch|ch.len_utf8()).sum::<usize>();if let Some(state)=&c.select{for option in &state.options{n+=option.value.len()+option.label.len();}for row in &state.rows{if let forms::SelectRow::Group{label,..}=row{n+=label.len();}}}n}).sum::<usize>();
 let label=&mut f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label;let size=label.len()+128*1024-payload-6;let old=std::mem::replace(label,"z".repeat(size));let tree=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);let editor=f.controls[&select].value.text();let before=(p.state.retained,p.state.dom_commits);p.begin_job();let error=p.runtime.execute("x.value='1234567';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("128 KiB"),"{error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(format!("{:?}",f.controls[&select].select),native);assert_eq!(f.controls[&select].value.text(),editor);assert_eq!((p.state.retained,p.state.dom_commits),before);
 f.controls.get_mut(&select).unwrap().select.as_mut().unwrap().options[1].label=old;p.begin_job();run(&mut d,&mut f,&mut p,"x.value='recovered';if(x.value!=='recovered'||document.getElementById('select').value!=='recovered')throw 'fresh payload recovery';");
}
#[test]
fn option_value_placeholder_validation_submission_and_reset_use_updated_option_values(){
 let mut d=crate::html::parse("<html><body><form id=form><select id=select name=pick required><option id=option value=''>Choose</option><option value=two>Two</option></select></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();
 assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),select=document.getElementById('select');x.value='Ready';");assert!(f.validate_submission(&d,owner,None).is_ok());assert_eq!(f.script_submit_request(&d,owner,&location,&location).unwrap().location.url.unwrap().query.as_deref(),Some("pick=Ready"));
 run(&mut d,&mut f,&mut p,"x.value='';");assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"x.removeAttribute('value');select.selectedIndex=1;");f.reset_in_document(&d,owner).unwrap();run(&mut d,&mut f,&mut p,"if(select.selectedIndex!==0||select.value!=='Choose'||x.value!=='Choose')throw 'updated native reset value';");assert!(f.validate_submission(&d,owner,None).is_ok());
}
